-- NV-STATUTE-EXPANSION-001 (2026-06-25) — foundational statute expansion
-- Generated from src/data/nv-statutes-expansion-2026-06.ts. Idempotent.
-- Counts: {"IN":215,"UK":41,"US":151,"EU":25,"SG":21,"GC":17} | total 470

BEGIN;

-- Self-contained guard: nv_statutes is normally provisioned at runtime by the
-- statute-seeding service (best-effort DDL). Recreate it here IF NOT EXISTS so a
-- fresh `createdb + psql -f` of the checked-in migration set applies cleanly. On
-- the live RDS the table already exists, so this is a no-op (column shape mirrors
-- the live RDS definition).
CREATE TABLE IF NOT EXISTS public.nv_statutes (
  id               serial PRIMARY KEY,
  act_title        text NOT NULL,
  act_short_title  text NOT NULL,
  jurisdiction     varchar NOT NULL,
  section_number   varchar NOT NULL,
  section_title    text,
  section_text     text,
  practice_area    varchar,
  keywords         text[],
  effective_date   date,
  amended_date     date,
  related_sections text[],
  is_repealed      boolean DEFAULT false,
  search_vector    tsvector,
  created_at       timestamptz DEFAULT now(),
  updated_at       timestamptz DEFAULT now(),
  CONSTRAINT nv_statutes_jurisdiction_act_short_title_section_number_key
    UNIQUE (jurisdiction, act_short_title, section_number)
);


-- Ensure the runtime role can read + future boot-seed these rows. Guarded so a
-- fresh DB without the nv_app role still applies cleanly.
DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'nv_app') THEN
    EXECUTE 'GRANT SELECT, INSERT, UPDATE ON public.nv_statutes TO nv_app';
    EXECUTE 'GRANT USAGE, SELECT ON SEQUENCE public.nv_statutes_id_seq TO nv_app';
  END IF;
END $$;

COMMIT;
